sites.find:
int run_length = 0;
cRSubLoc* cursor = cell;
int lane_cursor = lane;
while (lane_cursor
           < (int)(sizeof(runtime_cells[0])
               / sizeof(runtime_cells[0][0]))
       && cursor->IsSlide() != 0
       && (cursor->lane_and_flags & SUBLOC_FLAG_CORNER_OBJECT) == 0
       && (cursor->lane_and_flags & SUBLOC_FLAG_UNCACHED_BODY) != 0
       && (cursor->lane_and_flags
               & (SUBLOC_FLAG_WARNING_CACHE_FAMILY
                   | SUBLOC_FLAG_CACHE_FAMILY_SWAPPED))
           == 0) {
    ++run_length;
    ++cursor;
    ++lane_cursor;
}

replacements.text:
int run_length = 0;
unsigned int* cursor_lane_flags = cell_lane_flags;
int lane_cursor = lane;
while (lane_cursor
           < (int)(sizeof(runtime_cells[0])
               / sizeof(runtime_cells[0][0]))
       && CELL_FROM_LANE_FLAGS(cursor_lane_flags)->IsSlide() != 0
       && (*cursor_lane_flags & SUBLOC_FLAG_CORNER_OBJECT) == 0
       && (*cursor_lane_flags & SUBLOC_FLAG_UNCACHED_BODY) != 0
       && (*cursor_lane_flags
               & (SUBLOC_FLAG_WARNING_CACHE_FAMILY
                   | SUBLOC_FLAG_CACHE_FAMILY_SWAPPED))
           == 0) {
    ++run_length;
    cursor_lane_flags +=
        sizeof(cRSubLoc) / sizeof(unsigned int);
    ++lane_cursor;
}
